package io.github.iachimoe.tarballfs;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertSame;

import java.nio.file.Path;
import java.util.HashMap;
import java.util.Map;
import org.junit.jupiter.api.Test;

class ArchiveUriSupportMutaGate1Test {

  @Test
  void pathFromEnvResolvesPathFileAndFallbacks() {
    // null env
    assertNull(ArchiveUriSupport.pathFromEnv(null));

    // empty env
    assertNull(ArchiveUriSupport.pathFromEnv(new HashMap<String, Object>()));

    // unrelated keys only
    Map<String, Object> other = new HashMap<>();
    other.put("other", "/x");
    assertNull(ArchiveUriSupport.pathFromEnv(other));

    // Path instance under "path" is returned as the same object
    Path p = Path.of("/tmp/a.tar");
    Map<String, Object> m1 = new HashMap<>();
    m1.put("path", p);
    assertSame(p, ArchiveUriSupport.pathFromEnv(m1));

    // String under "path" is converted
    Map<String, Object> m2 = new HashMap<>();
    m2.put("path", "/tmp/b.tar");
    assertEquals(Path.of("/tmp/b.tar"), ArchiveUriSupport.pathFromEnv(m2));

    // "file" key used when "path" absent
    Map<String, Object> m3 = new HashMap<>();
    m3.put("file", "/tmp/c.tar");
    assertEquals(Path.of("/tmp/c.tar"), ArchiveUriSupport.pathFromEnv(m3));

    // "file" with Path instance returned as same object
    Path fp = Path.of("/tmp/d.tar");
    Map<String, Object> m4 = new HashMap<>();
    m4.put("file", fp);
    assertSame(fp, ArchiveUriSupport.pathFromEnv(m4));

    // "path" takes precedence over "file"
    Map<String, Object> m5 = new HashMap<>();
    m5.put("path", "/tmp/first.tar");
    m5.put("file", "/tmp/second.tar");
    assertEquals(Path.of("/tmp/first.tar"), ArchiveUriSupport.pathFromEnv(m5));

    // "path" explicitly null falls back to "file"
    Map<String, Object> m6 = new HashMap<>();
    m6.put("path", null);
    m6.put("file", "/tmp/fallback.tar");
    assertEquals(Path.of("/tmp/fallback.tar"), ArchiveUriSupport.pathFromEnv(m6));

    // non-String, non-Path object is converted via toString
    Map<String, Object> m7 = new HashMap<>();
    m7.put("path", new StringBuilder("/tmp/sb.tar"));
    assertEquals(Path.of("/tmp/sb.tar"), ArchiveUriSupport.pathFromEnv(m7));
  }
}

package io.github.iachimoe.tarballfs;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;

import java.net.URI;
import java.nio.file.Path;
import java.util.HashMap;
import java.util.Map;
import org.junit.jupiter.api.Test;

class ArchiveUriSupportMutaGate2Test {

  @Test
  void extractArchivePathBehaviors() {
    // env "path" takes precedence over URI
    Map<String, Object> env = new HashMap<>();
    env.put("path", Path.of("/env/path.tar"));
    env.put("file", Path.of("/env/file.tar"));
    assertEquals(
        Path.of("/env/path.tar"),
        ArchiveUriSupport.extractArchivePath(URI.create("tar:///uri/a.tar"), env, "tar"));

    // falls back to "file" key, with string value converted to Path
    Map<String, Object> fileEnv = new HashMap<>();
    fileEnv.put("file", "/env/fileonly.tar");
    assertEquals(
        Path.of("/env/fileonly.tar"),
        ArchiveUriSupport.extractArchivePath(URI.create("tar:///uri/a.tar"), fileEnv, "tar"));

    // env without path/file falls through to URI
    Map<String, Object> otherEnv = new HashMap<>();
    otherEnv.put("other", "x");
    assertEquals(
        Path.of("/uri/a.tar"),
        ArchiveUriSupport.extractArchivePath(URI.create("tar:///uri/a.tar"), otherEnv, "tar"));

    // null env uses URI path
    assertEquals(
        Path.of("/uri/a.tar"),
        ArchiveUriSupport.extractArchivePath(URI.create("tar:///uri/a.tar"), null, "tar"));

    // bang suffix is stripped
    assertEquals(
        Path.of("/uri/a.tar"),
        ArchiveUriSupport.extractArchivePath(
            URI.create("tar:///uri/a.tar!/dir/entry.txt"), null, "tar"));

    // opaque URI has null path: throws with label and URI in message
    IllegalArgumentException ex =
        assertThrows(
            IllegalArgumentException.class,
            () -> ArchiveUriSupport.extractArchivePath(URI.create("mailto:foo"), null, "LBL"));
    assertEquals("LBL URI does not contain a file path: mailto:foo", ex.getMessage());
  }
}

package io.github.iachimoe.tarballfs;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;

import java.net.URI;
import java.nio.file.Path;
import org.junit.jupiter.api.Test;

class ArchiveUriSupportMutaGate3Test {

  @Test
  void archiveKeyUriStripsEntrySuffixMatchesSchemeIgnoringCaseAndRejectsBadInput() {
    URI expected = URI.create("tar:" + Path.of("/tmp/a.tar").toAbsolutePath());

    // Entry suffix after '!' is stripped
    assertEquals(
        expected,
        ArchiveUriSupport.archiveKeyUri(URI.create("tar:///tmp/a.tar!/entry/file"), "tar", "tar:"));

    // No bang: path used as is
    assertEquals(
        expected,
        ArchiveUriSupport.archiveKeyUri(URI.create("tar:///tmp/a.tar"), "tar", "tar:"));

    // Scheme comparison is case-insensitive
    assertEquals(
        expected,
        ArchiveUriSupport.archiveKeyUri(URI.create("TAR:///tmp/a.tar!/e"), "tar", "tar:"));

    // Wrong scheme
    IllegalArgumentException wrongScheme =
        assertThrows(
            IllegalArgumentException.class,
            () -> ArchiveUriSupport.archiveKeyUri(URI.create("zip:///tmp/a.tar"), "tar", "tar:"));
    assertEquals("Unsupported URI scheme: zip", wrongScheme.getMessage());

    // Empty path
    IllegalArgumentException emptyPath =
        assertThrows(
            IllegalArgumentException.class,
            () -> ArchiveUriSupport.archiveKeyUri(URI.create("tar://host"), "tar", "tar:"));
    assertEquals("tar URI does not contain a file path: tar://host", emptyPath.getMessage());
  }
}

